/**
 * p13_coverage_recovery_planner.test.ts
 * P13 — CoverageRecoveryPlanner tests
 */

import * as fs from 'fs';
import * as path from 'path';

import {
    buildCoverageRecoveryPlan,
    validateCoverageRecoveryPlan,
    COVERAGE_RECOVERY_PLAN_VERSION,
    type CoverageRecoveryPlan,
} from '../CoverageRecoveryPlanner';
import {
    buildHorizonMaturityTracker,
    type HorizonMaturityTracker,
} from '../HorizonMaturityTracker';
import { parseSnapshotCorpusJsonl } from '../SimulationSnapshotCorpusAccumulator';
import type { CorpusMetrics } from '../CorpusMetricsStore';
import type { CorpusQualityGateResult } from '../CorpusQualityGate';

const CORPUS_PATH = path.resolve(process.cwd(), 'outputs/online_validation/simulation_snapshot_corpus.jsonl');
const P12_METRICS_PATH = path.resolve(process.cwd(), 'outputs/online_validation/p12_corpus_metrics_store.json');
const P12_QUALITY_PATH = path.resolve(process.cwd(), 'outputs/online_validation/p12_corpus_quality_gate.json');

function loadCorpus() {
    return parseSnapshotCorpusJsonl(fs.readFileSync(CORPUS_PATH, 'utf8'));
}

function loadJson<T>(filePath: string): T {
    return JSON.parse(fs.readFileSync(filePath, 'utf8')) as T;
}

function makeTinyTracker(overrides: Partial<HorizonMaturityTracker> = {}): HorizonMaturityTracker {
    return {
        trackerVersion: 'horizon-maturity-tracker-v0',
        trackerRunId: 'tiny-tracker',
        generatedAt: '2026-05-11T08:00:00.000Z',
        reviewDate: '2026-07-13',
        inputCorpusEntryCount: 6,
        totalEntries: 6,
        horizonSummaries: [
            {
                horizonLabel: '60D',
                totalCount: 6,
                readyCount: 0,
                blockedCount: 6,
                coverageRatio: 0,
                blockedReasonCounts: { WINDOW_NOT_DUE: 6 },
                earliestAsOfDate: '2026-05-11',
                latestAsOfDate: '2026-05-11',
                earliestTargetTradingDate: '2026-08-04',
                latestTargetTradingDate: '2026-08-04',
                dueCount: 0,
                notDueCount: 6,
                missingOutcomeCount: 0,
                maturityRatio: 0,
                maturityStatus: 'NOT_DUE_DOMINANT',
            },
        ],
        maturityStatus: 'IMMATURE',
        guardrails: {
            noProductionWrite: true,
            noSimulationWrite: true,
            noOptimizerWrite: true,
            noPerformanceClaim: true,
            noTradingSignal: true,
            observabilityOnly: true,
        },
        validationStatus: 'PASS',
        validationMessages: [],
        ...overrides,
    };
}

describe('CoverageRecoveryPlanner — P13', () => {
    const corpusEntries = loadCorpus();
    const corpusMetrics = loadJson<CorpusMetrics>(P12_METRICS_PATH);
    const corpusQualityGate = loadJson<CorpusQualityGateResult>(P12_QUALITY_PATH);
    const tracker = buildHorizonMaturityTracker(corpusEntries, {
        trackerRunId: 'p13-horizon-maturity-20260511-001',
        generatedAt: '2026-05-11T08:00:00.000Z',
        reviewDate: '2026-07-13',
    });

    const plan = buildCoverageRecoveryPlan(
        {
            horizonMaturityTracker: tracker,
            corpusQualityGate,
            corpusMetrics,
        },
        {
            recoveryRunId: 'p13-coverage-recovery-20260511-001',
            generatedAt: '2026-05-11T08:00:00.000Z',
            targetCoverageRatio: 0.5,
            targetHorizonCoverageGap: 0.35,
            targetUniqueAsOfDateCount: 10,
        },
    );

    it('has the expected plan version', () => {
        expect(plan.recoveryPlanVersion).toBe(COVERAGE_RECOVERY_PLAN_VERSION);
    });

    it('WAIT_FOR_MATURITY for 60D not due', () => {
        const h60d = plan.horizonRecoveryItems.find(item => item.horizonLabel === '60D')!;
        expect(h60d.recoveryNeed).toBe('WAIT_FOR_MATURITY');
        expect(h60d.topBlockedReason).toBe('WINDOW_NOT_DUE');
    });

    it('BACKFILL_MISSING_OUTCOME for missing outcome', () => {
        const tinyPlan = buildCoverageRecoveryPlan(
            {
                horizonMaturityTracker: makeTinyTracker({
                    horizonSummaries: [
                        {
                            horizonLabel: '20D',
                            totalCount: 6,
                            readyCount: 3,
                            blockedCount: 3,
                            coverageRatio: 0.5,
                            blockedReasonCounts: { OUTCOME_MISSING: 3 },
                            earliestAsOfDate: '2026-05-11',
                            latestAsOfDate: '2026-05-11',
                            earliestTargetTradingDate: '2026-06-08',
                            latestTargetTradingDate: '2026-06-08',
                            dueCount: 6,
                            notDueCount: 0,
                            missingOutcomeCount: 3,
                            maturityRatio: 1,
                            maturityStatus: 'MISSING_OUTCOME_DOMINANT',
                        },
                    ],
                    maturityStatus: 'PARTIALLY_MATURE',
                }),
                corpusQualityGate,
                corpusMetrics,
            },
            {
                recoveryRunId: 'p13-coverage-recovery-missing-outcome',
                generatedAt: '2026-05-11T08:00:00.000Z',
                targetCoverageRatio: 0.5,
                targetHorizonCoverageGap: 0.35,
                targetUniqueAsOfDateCount: 10,
            },
        );
        expect(tinyPlan.horizonRecoveryItems[0].recoveryNeed).toBe('BACKFILL_MISSING_OUTCOME');
    });

    it('EXPAND_CORPUS when corpus too small', () => {
        const smallPlan = buildCoverageRecoveryPlan(
            {
                horizonMaturityTracker: makeTinyTracker({
                    inputCorpusEntryCount: 3,
                    totalEntries: 3,
                    horizonSummaries: [
                        {
                            horizonLabel: '5D',
                            totalCount: 3,
                            readyCount: 1,
                            blockedCount: 2,
                            coverageRatio: 1 / 3,
                            blockedReasonCounts: { WINDOW_NOT_DUE: 2 },
                            earliestAsOfDate: '2026-05-11',
                            latestAsOfDate: '2026-05-11',
                            earliestTargetTradingDate: '2026-05-18',
                            latestTargetTradingDate: '2026-05-18',
                            dueCount: 3,
                            notDueCount: 0,
                            missingOutcomeCount: 0,
                            maturityRatio: 1,
                            maturityStatus: 'PARTIAL',
                        },
                    ],
                    maturityStatus: 'PARTIALLY_MATURE',
                }),
                corpusQualityGate,
                corpusMetrics,
            },
            {
                recoveryRunId: 'p13-coverage-recovery-small',
                generatedAt: '2026-05-11T08:00:00.000Z',
                targetCoverageRatio: 0.5,
                targetHorizonCoverageGap: 0.35,
                targetUniqueAsOfDateCount: 10,
            },
        );
        expect(smallPlan.horizonRecoveryItems[0].recoveryNeed).toBe('EXPAND_CORPUS');
    });

    it('guardrails are all true', () => {
        expect(plan.guardrails.noProductionWrite).toBe(true);
        expect(plan.guardrails.noOptimizerWrite).toBe(true);
        expect(plan.guardrails.noPerformanceClaim).toBe(true);
        expect(plan.guardrails.noTradingSignal).toBe(true);
        expect(plan.guardrails.observabilityOnly).toBe(true);
    });

    it('productionWriteAllowed is false', () => {
        for (const item of plan.horizonRecoveryItems) {
            expect(item.productionWriteAllowed).toBe(false);
        }
    });

    it('optimizerWriteAllowed is false', () => {
        for (const item of plan.horizonRecoveryItems) {
            expect(item.optimizerWriteAllowed).toBe(false);
        }
    });

    it('plan status is DATA_LIMITED for current corpus', () => {
        expect(plan.recoveryStatus).toBe('DATA_LIMITED');
    });

    it('PRODUCTION_READY is rejected', () => {
        const tampered = { ...plan, recoveryStatus: 'PRODUCTION_READY' as any };
        const result = validateCoverageRecoveryPlan(tampered);
        expect(result.validationStatus).toBe('FAIL');
        expect(result.validationMessages.join(' ')).toMatch(/PRODUCTION_READY/);
    });

    it('forbidden claims are rejected', () => {
        const tampered = { ...plan, recommendedActions: ['profit', 'outperform'] };
        const result = validateCoverageRecoveryPlan(tampered as CoverageRecoveryPlan);
        expect(result.validationStatus).toBe('FAIL');
        expect(result.validationMessages.join(' ')).toMatch(/forbidden/i);
    });

    it('valid plan passes validation', () => {
        expect(validateCoverageRecoveryPlan(plan).validationStatus).toBe('PASS');
    });
});

/**
 * p14_backfill_quality_impact_preview.test.ts
 * P14 — BackfillQualityImpactPreview tests
 */

import * as fs from 'fs';
import * as path from 'path';

import {
    buildBackfillQualityImpactPreview,
    validateBackfillQualityImpactPreview,
    BACKFILL_QUALITY_IMPACT_PREVIEW_VERSION,
} from '../BackfillQualityImpactPreview';
import { summarizeOutcomeBackfillRehearsal } from '../OutcomeBackfillRehearsalEngine';
import {
    buildOutcomeBackfillRehearsal,
} from '../OutcomeBackfillRehearsalEngine';
import {
    selectOutcomeBackfillCandidates,
} from '../OutcomeBackfillCandidateSelector';
import { parseSnapshotCorpusJsonl } from '../SimulationSnapshotCorpusAccumulator';
import type { CorpusMetrics } from '../CorpusMetricsStore';
import type { CorpusQualityGateResult } from '../CorpusQualityGate';

const CORPUS_PATH = path.resolve(process.cwd(), 'outputs/online_validation/simulation_snapshot_corpus.jsonl');
const P12_METRICS_PATH = path.resolve(process.cwd(), 'outputs/online_validation/p12_corpus_metrics_store.json');
const P12_QUALITY_PATH = path.resolve(process.cwd(), 'outputs/online_validation/p12_corpus_quality_gate.json');

function loadCorpus() {
    return parseSnapshotCorpusJsonl(fs.readFileSync(CORPUS_PATH, 'utf8'));
}

function loadJson<T>(filePath: string): T {
    return JSON.parse(fs.readFileSync(filePath, 'utf8')) as T;
}

describe('BackfillQualityImpactPreview — P14', () => {
    const corpusEntries = loadCorpus();
    const corpusMetrics = loadJson<CorpusMetrics>(P12_METRICS_PATH);
    const corpusQualityGate = loadJson<CorpusQualityGateResult>(P12_QUALITY_PATH);
    const selection = selectOutcomeBackfillCandidates(corpusEntries, {
        selectorRunId: 'p14-selector-20260511-001',
        generatedAt: '2026-05-11T09:00:00.000Z',
        reviewDate: '2026-07-13',
        maxCandidates: 20,
    });
    const rehearsal = buildOutcomeBackfillRehearsal(selection, {
        rehearsalRunId: 'p14-rehearsal-20260511-001',
        generatedAt: '2026-05-11T09:00:00.000Z',
        dryRun: true,
        mockOutcomeProvider: (symbol, horizonLabel) => {
            if (horizonLabel === '20D') {
                return {
                    closePriceAtPrediction: 100,
                    closePriceAtOutcome: 110,
                    returnPct: 0.1,
                    priceSource: 'mock',
                    outcomeAvailable: true,
                };
            }
            return null;
        },
    });
    const summary = summarizeOutcomeBackfillRehearsal(rehearsal);
    const preview = buildBackfillQualityImpactPreview(
        {
            currentCorpusMetrics: corpusMetrics,
            currentCorpusQualityGate: corpusQualityGate,
            rehearsalSummary: summary,
        },
        {
            previewRunId: 'p14-backfill-impact-preview-001',
            generatedAt: '2026-05-11T09:00:00.000Z',
        },
    );

    it('projectedCoverageRatio improves after transitions', () => {
        expect(preview.projectedCoverageRatio).toBeGreaterThan(corpusMetrics.coverageRatio);
    });

    it('no material change when no transitions', () => {
        const noTransitionPreview = buildBackfillQualityImpactPreview(
            {
                currentCorpusMetrics: corpusMetrics,
                currentCorpusQualityGate: corpusQualityGate,
                rehearsalSummary: {
                    ...summary,
                    transitionCounts: {
                        BLOCKED_TO_READY: 0,
                        REMAINS_BLOCKED: summary.rehearsedCount + summary.stillBlockedCount,
                        NO_CHANGE: 0,
                    },
                    readyAfterRehearsalCount: corpusMetrics.readyCount,
                    blockedAfterRehearsalCount: corpusMetrics.blockedCount,
                },
            },
            {
                previewRunId: 'p14-backfill-impact-preview-nochange',
                generatedAt: '2026-05-11T09:00:00.000Z',
            },
        );
        expect(noTransitionPreview.impactStatus).toBe('NO_MATERIAL_CHANGE');
        expect(noTransitionPreview.projectedCoverageRatio).toBeCloseTo(corpusMetrics.coverageRatio, 4);
    });

    it('projectedQualityStatus remains DATA_LIMITED or BLOCKED when below threshold', () => {
        expect(['DATA_LIMITED', 'BLOCKED']).toContain(preview.projectedQualityStatus);
    });

    it('has correct preview version', () => {
        expect(preview.previewVersion).toBe(BACKFILL_QUALITY_IMPACT_PREVIEW_VERSION);
    });

    it('guardrails are all true', () => {
        expect(preview.guardrails.noProductionWrite).toBe(true);
        expect(preview.guardrails.noCorpusWrite).toBe(true);
        expect(preview.guardrails.noOptimizerWrite).toBe(true);
        expect(preview.guardrails.noPerformanceClaim).toBe(true);
        expect(preview.guardrails.noTradingSignal).toBe(true);
        expect(preview.guardrails.observabilityOnly).toBe(true);
    });

    it('validation passes for valid preview', () => {
        expect(preview.validationStatus).toBe('PASS');
        expect(validateBackfillQualityImpactPreview(preview).validationStatus).toBe('PASS');
    });

    it('PRODUCTION_READY is rejected', () => {
        const mutated = { ...preview, projectedQualityStatus: 'PRODUCTION_READY' as any };
        const result = validateBackfillQualityImpactPreview(mutated);
        expect(result.validationStatus).toBe('FAIL');
    });

    it('forbidden claims are rejected', () => {
        const mutated = { ...preview, notes: ['profit', 'outperform'] };
        const result = validateBackfillQualityImpactPreview(mutated as typeof preview);
        expect(result.validationStatus).toBe('FAIL');
    });
});

import * as fs from 'fs';
import * as path from 'path';

import { parseSnapshotCorpusJsonl } from '../SimulationSnapshotCorpusAccumulator';
import { selectOutcomeBackfillCandidates } from '../OutcomeBackfillCandidateSelector';
import { buildOutcomeBackfillRehearsal } from '../OutcomeBackfillRehearsalEngine';
import { buildBackfillQualityImpactPreview } from '../BackfillQualityImpactPreview';
import { buildOutcomeBackfillGovernanceGate } from '../OutcomeBackfillGovernanceGate';
import { buildBackfillWritePathContract } from '../BackfillWritePathContract';
import {
    buildBackfillManualReviewPackage,
    validateBackfillManualReviewPackage,
} from '../BackfillManualReviewPackage';
import type { CorpusMetrics } from '../CorpusMetricsStore';
import type { CorpusQualityGateResult } from '../CorpusQualityGate';
import type { OutcomeBackfillRehearsalSummary } from '../OutcomeBackfillRehearsalEngine';

const CORPUS_PATH = path.resolve(process.cwd(), 'outputs/online_validation/simulation_snapshot_corpus.jsonl');
const P12_METRICS_PATH = path.resolve(process.cwd(), 'outputs/online_validation/p12_corpus_metrics_store.json');
const P12_QUALITY_PATH = path.resolve(process.cwd(), 'outputs/online_validation/p12_corpus_quality_gate.json');

function loadCorpus() {
    return parseSnapshotCorpusJsonl(fs.readFileSync(CORPUS_PATH, 'utf8'));
}

function loadJson<T>(filePath: string): T {
    return JSON.parse(fs.readFileSync(filePath, 'utf8')) as T;
}

describe('BackfillManualReviewPackage — P15', () => {
    const corpusEntries = loadCorpus();
    const corpusMetrics = loadJson<CorpusMetrics>(P12_METRICS_PATH);
    const currentQualityGate = loadJson<CorpusQualityGateResult>(P12_QUALITY_PATH);
    const candidateSelection = selectOutcomeBackfillCandidates(corpusEntries, {
        selectorRunId: 'p15-selector-20260511-001',
        generatedAt: '2026-05-11T09:15:00.000Z',
        reviewDate: '2026-07-13',
        maxCandidates: 20,
    });
    const rehearsal = buildOutcomeBackfillRehearsal(candidateSelection, {
        rehearsalRunId: 'p15-rehearsal-20260511-001',
        generatedAt: '2026-05-11T09:15:00.000Z',
        dryRun: true,
        mockOutcomeProvider: (symbol, horizonLabel, targetTradingDate) => {
            if (horizonLabel === '20D' && symbol === candidateSelection.candidates[0]?.symbol && targetTradingDate === candidateSelection.candidates[0]?.targetTradingDate) {
                return {
                    closePriceAtPrediction: 100,
                    closePriceAtOutcome: 110,
                    returnPct: 0.1,
                    priceSource: 'mock',
                    outcomeAvailable: true,
                };
            }
            return null;
        },
    });
    const rehearsalSummary: OutcomeBackfillRehearsalSummary = {
        ...rehearsal,
        transitionCounts: {
            BLOCKED_TO_READY: rehearsal.rehearsalItems.filter(item => item.transitionType === 'BLOCKED_TO_READY').length,
            REMAINS_BLOCKED: rehearsal.rehearsalItems.filter(item => item.transitionType === 'REMAINS_BLOCKED').length,
            NO_CHANGE: rehearsal.rehearsalItems.filter(item => item.transitionType === 'NO_CHANGE').length,
        },
        byHorizon: rehearsal.rehearsalItems.reduce((acc, item) => {
            if (!acc[item.horizonLabel]) acc[item.horizonLabel] = { ready: 0, blocked: 0 };
            if (item.proposedSnapshotStatus === 'SNAPSHOT_READY') acc[item.horizonLabel].ready += 1;
            else acc[item.horizonLabel].blocked += 1;
            return acc;
        }, {} as Record<string, { ready: number; blocked: number }>),
        bySymbol: rehearsal.rehearsalItems.reduce((acc, item) => {
            if (!acc[item.symbol]) acc[item.symbol] = { ready: 0, blocked: 0 };
            if (item.proposedSnapshotStatus === 'SNAPSHOT_READY') acc[item.symbol].ready += 1;
            else acc[item.symbol].blocked += 1;
            return acc;
        }, {} as Record<string, { ready: number; blocked: number }>),
        readyAfterRehearsalCount: rehearsal.rehearsalItems.filter(item => item.proposedSnapshotStatus === 'SNAPSHOT_READY').length,
        blockedAfterRehearsalCount: rehearsal.rehearsalItems.filter(item => item.proposedSnapshotStatus === 'SNAPSHOT_BLOCKED').length,
    };
    const preview = buildBackfillQualityImpactPreview(
        {
            currentCorpusMetrics: corpusMetrics,
            currentCorpusQualityGate: currentQualityGate,
            rehearsalSummary,
        },
        {
            previewRunId: 'p15-preview-20260511-001',
            generatedAt: '2026-05-11T09:15:00.000Z',
        },
    );
    const governanceGate = buildOutcomeBackfillGovernanceGate(
        {
            candidateSelection,
            rehearsal,
            qualityImpactPreview: preview,
            currentCorpusLineCount: corpusEntries.length,
            currentQualityGate,
        },
        {
            governanceRunId: 'p15-governance-20260511-001',
            generatedAt: '2026-05-11T09:15:00.000Z',
            requireManualApproval: true,
            minRehearsedCount: 1,
            minBlockedToReadyCount: 1,
            maxAllowedCorpusWritePermission: false,
        },
    );
    const writePathContract = buildBackfillWritePathContract(
        {
            governanceGate,
            rehearsal,
            qualityImpactPreview: preview,
        },
        {
            contractRunId: 'p15-contract-20260511-001',
            generatedAt: '2026-05-11T09:15:00.000Z',
        },
    );
    const pkg = buildBackfillManualReviewPackage(
        {
            governanceGate,
            writePathContract,
            candidateSelection,
            rehearsal,
            qualityImpactPreview: preview,
        },
        {
            packageRunId: 'p15-package-20260511-001',
            generatedAt: '2026-05-11T09:15:00.000Z',
        },
    );

    it('READY_FOR_HUMAN_REVIEW when governance gate ready', () => {
        expect(pkg.reviewStatus).toBe('READY_FOR_HUMAN_REVIEW');
    });

    it('required reviewer decisions include no corpus write', () => {
        expect(pkg.requiredReviewerDecisions.map(item => item.decision)).toEqual(
            expect.arrayContaining(['confirm no corpus write']),
        );
    });

    it('forbidden decisions include production backfill / optimizer / trading action', () => {
        expect(pkg.forbiddenDecisions.map(item => item.decision)).toEqual(
            expect.arrayContaining([
                'approve production backfill',
                'approve corpus write',
                'approve optimizer',
                'approve trading action',
            ]),
        );
    });

    it('projected coverage is not performance', () => {
        const summaryText = JSON.stringify(pkg.reviewSummary);
        expect(summaryText).not.toMatch(/performance/i);
    });

    it('validation passes for valid package', () => {
        expect(pkg.validationStatus).toBe('PASS');
        expect(validateBackfillManualReviewPackage(pkg).validationStatus).toBe('PASS');
    });

    it('PRODUCTION_READY rejected', () => {
        const mutated = { ...pkg, reviewStatus: 'PRODUCTION_READY' as any };
        const result = validateBackfillManualReviewPackage(mutated);
        expect(result.validationStatus).toBe('FAIL');
    });

    it('forbidden claims rejected', () => {
        const mutated = { ...pkg, risks: ['profit', 'outperform'] };
        const result = validateBackfillManualReviewPackage(mutated as typeof pkg);
        expect(result.validationStatus).toBe('FAIL');
    });
});

import {
